function c(n){if(n<=1)return 0;if(n===2)return 1;return 2*(Math.log(n-1)+.5772156649)-2*(n-1)/n}
function train({trees=64,seed=1977}={}){let random=rng(seed),trainRows=historical.map((t,i)=>vector({...t,counterpart:i%5===0?t.amount*(1-random()*.004):null})),size=128,limit=Math.ceil(Math.log2(size));function build(data,depth){if(data.length<=1||depth>=limit)return {n:data.length};let candidates=names.map((_,j)=>{let vals=data.map(x=>x[j]);return {j,min:Math.min(...vals),max:Math.max(...vals)}}).filter(x=>x.max>x.min);if(!candidates.length)return {n:data.length};let f=candidates[Math.floor(random()*candidates.length)],split=f.min+random()*(f.max-f.min),left=data.filter(x=>x[f.j]<split),right=data.filter(x=>x[f.j]>=split);if(!left.length||!right.length)return {n:data.length};return {j:f.j,split,left:build(left,depth+1),right:build(right,depth+1)}}let forest=Array.from({length:trees},()=>{let a=[...trainRows];for(let i=a.length-1;i>0;i--){let j=Math.floor(random()*(i+1));[a[i],a[j]]=[a[j],a[i]]}return build(a.slice(0,size),0)});return {forest,size,trainRows};}
let cached=null;
function machine(rows,{threshold=.62,trees=64}={}){if(!cached||cached.trees!==trees)cached={...train({trees}),trees};let {forest,size,trainRows}=cached;function path(x,node,depth=0){return node.j===undefined?depth+c(node.n):path(x,x[node.j]<node.split?node.left:node.right,depth+1)}let centres=names.map((_,j)=>mean(trainRows.map(x=>x[j]))),spreads=names.map((_,j)=>sd(trainRows.map(x=>x[j])));return rows.map(t=>{let x=vector(t),avg=mean(forest.map(tree=>path(x,tree))),raw=2**(-avg/c(size)),flagged=raw>threshold,context=names.map((name,j)=>({name,deviation:spreads[j]?Math.abs(x[j]-centres[j])/spreads[j]:0})).sort((a,b)=>b.deviation-a.deviation).slice(0,3);let evidence=`Isolation Forest score ${raw.toFixed(3)} > cutoff ${threshold.toFixed(2)}; average path length ${avg.toFixed(2)} across ${trees} trees. Largest baseline feature deviations: ${context.map(d=>d.name).join(', ')}. These are contextual indicators, not causal feature attributions.`;return {...t,flagged,rawScore:raw,score:Math.round(raw*99),severity:raw>threshold+.08?'High':'Medium',hits:flagged?[{id:'ML',kind:'machine',name:'Isolation Forest outlier',description:evidence,evidence,threshold}]:[]}})}
